CREATE   VIEW [RegsBI].[vwricsv1_surveyresponse_CE]
AS
SELECT 
	[ricsv1_surveyresponseId] AS [rics_surveyresponseid]
	, [ricsv1_TotalQuestions] AS [rics_totalquestions]
	, [ricsv1_TotalAnswersRequired] AS [rics_totalanswersrequired]
	, [ricsv1_TotalAnswersProvided] AS [rics_totalanswersprovided]
	, [ricsv1_Status] AS [rics_status]
	, [ricsv1_surveyrequest] AS [rics_surveyrequest]
	, [ricsv1_Survey] AS [rics_survey]
	, [statuscode]
	, [statuscode_description]
	, [statecode]
	, [statecode_description]
	, [ricsv1_Returnee] AS [rics_returnee]
	, [ricsv1_ReturneeName] AS [rics_returneeName]
	, [ricsv1_responsescore] AS [rics_responsescore]
	, [overriddencreatedon]
	, [owningbusinessunit]
	, [owningbusinessunitName]
	, [OwnerIdName]
	, [ricsv1_name] AS [rics_name]
	, [modified_on] AS [modifiedon]
	, [modifiedbyName]
	, [ricsv1_DateStarted] AS [rics_datestarted]
	, [ricsv1_DateCompleted] AS [rics_datecompleted]
	, [Created_On] AS [createdon]
	, [CreatedByName]
FROM [CE].[vwricsv1_surveyresponse]
